package com.marketplace;
import java.util.*;import jakarta.servlet.http.*;import org.springframework.web.bind.annotation.*;import org.springframework.transaction.annotation.Transactional;import org.springframework.beans.factory.annotation.Value;
@RestController @RequestMapping("/api") public class Orders {
 final Db d;final Access a;final Commerce c;final boolean demo;Orders(Db d,Access a,Commerce c,@Value("${app.demo}")boolean demo){this.d=d;this.a=a;this.c=c;this.demo=demo;}
 @PostMapping("/checkout/quote") Object quote(HttpSession s,@RequestBody Commerce.Checkout b){return c.quote(a.role(s,"CUSTOMER"),b);}
 @PostMapping("/checkout") Object checkout(HttpSession s,@RequestHeader("Idempotency-Key")String k,@RequestBody Commerce.Checkout b){if(!demo)throw new Failure(503,"PAYMENTS_DISABLED","Demo payments disabled; configure a production provider before checkout");return c.checkout(a.role(s,"CUSTOMER"),k,b);}
 @GetMapping("/orders") Object list(HttpSession s){return d.all("select * from orders where user_id=? order by id desc",a.uid(s));}
 Map<String,Object> detail(long id){var o=d.one("select *,address::text as shipping_address_json from orders where id=?",id);o.put("address",OrderPresentation.shippingAddress((String)o.remove("shipping_address_json")));o.put("items",d.all("select * from order_items where order_id=? order by id",id));var portions=d.all("select so.*,s.name seller from seller_orders so join stores s on s.id=so.seller_id where order_id=? order by so.id",id);o.put("portions",portions);o.put("can_cancel",OrderPresentation.canCancel(Db.str(o,"payment_state"),portions));o.put("returns",d.all("select * from returns where order_id=?",id));o.put("refunds",d.all("select * from refunds where order_id=?",id));return o;}
 @GetMapping("/orders/{id}") Object order(HttpSession s,@PathVariable long id){d.one("select id from orders where id=? and user_id=?",id,a.uid(s));return detail(id);}
 @PostMapping("/orders/{id}/cancel") Object cancel(HttpSession s,@PathVariable long id){return c.cancel(a.uid(s),id);}
 record Payment(String eventId,String outcome){}
 @PostMapping("/orders/{id}/demo-payment") Object pay(HttpSession s,@PathVariable long id,@RequestBody Payment p){if(!demo)throw new Failure(404,"NOT_FOUND","Not available");d.one("select id from orders where id=? and user_id=?",id,a.uid(s));return c.settle(id,p.eventId(),p.outcome());}
 @PostMapping("/orders/{id}/returns/{portion}") @Transactional Object returnRequest(HttpSession s,@PathVariable long id,@PathVariable long portion,@RequestBody Map<String,String>b){Catalog.check(b.get("reason"),5,1000);d.one("select o.id from orders o join seller_orders so on so.order_id=o.id where o.id=? and o.user_id=? and so.id=? and o.payment_state='PAID' and so.fulfillment='DELIVERED' and o.created_at>=now()-interval '30 days'",id,a.uid(s),portion);long rid=d.id("insert into returns(order_id,seller_order_id,reason) values(?,?,?) on conflict(seller_order_id) do update set reason=returns.reason returning id",id,portion,b.get("reason"));return Map.of("id",rid);}
}
